#!/usr/bin/env node

const path = require('node:path');
const http = require('node:http');
const { spawn, execSync } = require('node:child_process');
const db = require('../data/db.js');

const args = process.argv.slice(2);
const command = args[0];

async function main() {
  if (!command) {
    await launchDashboard();
    return;
  }

  switch (command) {
    case 'serve':
      runServer();
      break;

    case 'stop':
      await stopServer();
      break;

    case 'restart':
      await restartServer();
      break;

    case 'status':
      await showStatus();
      break;

    case 'mcp':
      runMcp();
      break;

    case 'add':
      handleAdd(args.slice(1));
      break;

    case 'list':
      handleList(args.slice(1));
      break;

    case 'task':
      handleTaskCommand(args.slice(1));
      break;

    case 'stats':
      console.log(JSON.stringify(db.getStats(), null, 2));
      break;

    case 'watchdog':
      // Real health check — delegate to the script
      require('node:child_process').spawnSync(
        'node',
        [path.join(__dirname, '..', 'scripts', 'watchdog.js')],
        { stdio: 'inherit' }
      );
      break;

    case 'scan-repos':
      // Real GitHub trending scan — delegate to the scraper script
      require('node:child_process').spawnSync(
        'node',
        [path.join(__dirname, '..', 'scripts', 'repo_star_tracker.js')],
        { stdio: 'inherit' }
      );
      break;

    case 'help':
    case '--help':
    case '-h':
      printHelp();
      break;

    default:
      console.error(`Unknown subcommand: ${command}`);
      printHelp();
      process.exit(1);
  }
}

async function launchDashboard() {
  const port = process.env.DAILY_PORT || 3456;
  const isRunning = await checkPortRunning(port);

  if (!isRunning) {
    console.log(`Starting Daily background server on port ${port}...`);
    spawnBackgroundServer();
    await new Promise(r => setTimeout(r, 600));
  }

  const url = `http://localhost:${port}`;
  console.log(`\n✨ Daily Workspace Dashboard active at: ${url}\n`);

  try {
    if (process.platform === 'darwin') {
      execSync(`open ${url}`);
    } else if (process.platform === 'win32') {
      execSync(`start ${url}`);
    } else {
      execSync(`xdg-open ${url} >/dev/null 2>&1 || true`);
    }
  } catch (e) {
    console.log(`Open ${url} in your browser.`);
  }
}

function spawnBackgroundServer() {
  const serverPath = path.join(__dirname, '..', 'server', 'index.js');
  const child = spawn('node', [serverPath], {
    detached: true,
    stdio: 'ignore'
  });
  child.unref();
}

async function stopServer() {
  const port = process.env.DAILY_PORT || 3456;
  const isRunning = await checkPortRunning(port);

  if (!isRunning) {
    console.log(`Daily server is not running on port ${port}.`);
    return;
  }

  try {
    let killed = false;
    try {
      const pids = execSync(`lsof -t -i:${port} 2>/dev/null || fuser ${port}/tcp 2>/dev/null || pgrep -f "daily serve|server/index.js"`)
        .toString()
        .trim()
        .split('\n')
        .map(s => s.trim())
        .filter(Boolean);

      for (const pid of pids) {
        if (pid && pid !== String(process.pid)) {
          execSync(`kill -9 ${pid} 2>/dev/null || true`);
          killed = true;
        }
      }
    } catch (e) {
      // Fallback
    }

    console.log(`🛑 Daily background server on port ${port} has been stopped.`);
  } catch (e) {
    console.error(`Failed to stop server: ${e.message}`);
  }
}

async function restartServer() {
  const port = process.env.DAILY_PORT || 3456;
  console.log(`Restarting Daily server...`);
  await stopServer();
  await new Promise(r => setTimeout(r, 600));
  spawnBackgroundServer();
  await new Promise(r => setTimeout(r, 600));
  console.log(`✨ Daily server restarted successfully at http://localhost:${port}`);
}

async function showStatus() {
  const port = process.env.DAILY_PORT || 3456;
  const isRunning = await checkPortRunning(port);

  console.log('\n=== DAILY WORKSPACE STATUS ===\n');
  console.log(`Server Status:  ${isRunning ? '🟢 ONLINE (http://localhost:' + port + ')' : '🔴 OFFLINE'}`);

  if (isRunning) {
    try {
      const res = await fetch(`http://localhost:${port}/api/stats`);
      const stats = await res.json();
      console.log(`Total Feed:     ${stats.updates.total} entries (${stats.updates.unread} unread)`);
      console.log(`Cron Tasks:     ${stats.tasks.active} active / ${stats.tasks.total} total`);
      console.log(`MCP Server:     Stdio Active`);
    } catch (e) {
      // ignore
    }
  }
  console.log(`Database Path:  /home/zius/.daily/data/daily.db\n`);
}

function checkPortRunning(port) {
  return new Promise((resolve) => {
    const req = http.get(`http://localhost:${port}/api/stats`, (res) => {
      resolve(res.statusCode === 200);
    });
    req.on('error', () => resolve(false));
    req.setTimeout(500, () => {
      req.destroy();
      resolve(false);
    });
  });
}

function runServer() {
  console.log('Starting Daily API Server & Scheduler in foreground...');
  const { startServer } = require('../server/index.js');
  startServer();
}

function runMcp() {
  require('../mcp/index.js');
}

function handleAdd(cmdArgs) {
  const params = parseFlags(cmdArgs);
  const title = params.title || params.t;
  const category = params.category || params.c || 'custom';
  const content = params.content || params.m || params.markdown;
  const tagsStr = params.tags || '';

  if (!title || !content) {
    console.error('Error: --title and --content flags are required.');
    console.log('\nExample:\n  daily add --title "New AI Framework" --category ai_tool --content "# Content here" --tags "ai,js"\n');
    process.exit(1);
  }

  const tags = tagsStr ? tagsStr.split(',').map(s => s.trim()) : [];
  const created = db.addUpdate({
    title,
    category,
    markdown_content: content,
    tags,
    source_agent: params.agent || 'cli'
  });

  console.log(`\n✅ Added Daily Update #${created.id}`);
  console.log(`Title: ${created.title}`);
  console.log(`Category: ${created.category}`);
  console.log(`Tags: ${created.tags.join(', ')}\n`);
}

function handleList(cmdArgs) {
  const params = parseFlags(cmdArgs);
  const limit = params.limit ? parseInt(params.limit, 10) : 10;
  const category = params.category || params.c;

  const updates = db.getUpdates({ category, limit });

  console.log(`\n=== DAILY INTELLIGENCE FEED (${updates.length} entries) ===\n`);
  if (updates.length === 0) {
    console.log('No updates found.');
    return;
  }

  updates.forEach((u) => {
    const badge = `[${u.category.toUpperCase()}]`;
    const readMark = u.read_status ? '✓' : '• UNREAD';
    const dateStr = new Date(u.created_at).toLocaleString();
    console.log(`ID #${u.id} ${readMark} | ${badge} ${u.title}`);
    console.log(`   Date: ${dateStr} | Source: ${u.source_agent} | Tags: ${u.tags.join(', ')}`);
    if (u.metadata && u.metadata.repo_url) {
      console.log(`   Repo: ${u.metadata.repo_url} (${u.metadata.star_growth || ''})`);
    }
    console.log('---');
  });
}

function handleTaskCommand(taskArgs) {
  const sub = taskArgs[0];
  if (!sub || sub === 'list') {
    const tasks = db.getTasks();
    console.log('\n=== AUTONOMOUS TASKS & CRON JOBS ===\n');
    console.log(formatTaskTable(tasks));
    return;
  }

  if (sub === 'trigger') {
    const taskId = taskArgs[1];
    if (!taskId) {
      console.error('Usage: daily task trigger <task_id>');
      process.exit(1);
    }
    console.log(`Triggering task "${taskId}"...`);
    const scheduler = require('../server/scheduler.js');
    scheduler.runTask(taskId).then((res) => {
      console.log(`\nExecution ${res.success ? 'SUCCESSFUL' : 'FAILED'} (${res.durationMs}ms)`);
      console.log(`Output:\n${res.output}\n`);
    });
    return;
  }

  if (sub === 'pause' || sub === 'resume') {
    const taskId = taskArgs[1];
    if (!taskId) {
      console.error(`Usage: daily task ${sub} <task_id>`);
      process.exit(1);
    }
    const newStatus = sub === 'pause' ? 'paused' : 'active';
    const updated = db.updateTask(taskId, { status: newStatus });
    console.log(`✅ Task "${taskId}" status changed to: ${updated.status}`);
    return;
  }

  if (sub === 'add') {
    const params = parseFlags(taskArgs.slice(1));
    if (!params.id || !params.name || !params.cmd || !params.schedule) {
      console.error('Usage: daily task add --id <id> --name <name> --cmd <command> --schedule <cron/interval>');
      process.exit(1);
    }
    const created = db.addTask({
      id: params.id,
      name: params.name,
      command_or_prompt: params.cmd,
      schedule: params.schedule,
      status: 'active'
    });
    console.log(`✅ Autonomous task "${created.id}" created.`);
    return;
  }

  console.error(`Unknown task subcommand: ${sub}`);
  console.log('Supported: daily task list | daily task trigger <id> | daily task pause <id> | daily task resume <id>');
}

function formatTaskTable(tasks) {
  if (tasks.length === 0) return 'No tasks registered.';

  const header = '| TASK ID             | NAME                             | SCHEDULE         | STATUS   | LAST RUN            |';
  const sep    = '|---------------------|----------------------------------|------------------|----------|---------------------|';
  const rows = tasks.map(t => {
    const id = pad(t.id, 19);
    const name = pad(t.name.slice(0, 32), 32);
    const sched = pad(t.schedule.slice(0, 16), 16);
    const status = pad(t.status.toUpperCase(), 8);
    const lastRun = pad(t.last_run_at ? new Date(t.last_run_at).toLocaleTimeString() : 'Never', 19);
    return `| ${id} | ${name} | ${sched} | ${status} | ${lastRun} |`;
  });

  return [header, sep, ...rows].join('\n');
}

function pad(str, len) {
  str = String(str || '');
  if (str.length >= len) return str.slice(0, len);
  return str + ' '.repeat(len - str.length);
}

function parseFlags(argsArr) {
  const flags = {};
  for (let i = 0; i < argsArr.length; i++) {
    const arg = argsArr[i];
    if (arg.startsWith('--')) {
      const key = arg.slice(2);
      const next = argsArr[i + 1];
      if (next && !next.startsWith('-')) {
        flags[key] = next;
        i++;
      } else {
        flags[key] = true;
      }
    } else if (arg.startsWith('-')) {
      const key = arg.slice(1);
      const next = argsArr[i + 1];
      if (next && !next.startsWith('-')) {
        flags[key] = next;
        i++;
      } else {
        flags[key] = true;
      }
    }
  }
  return flags;
}

function printHelp() {
  console.log(`
Daily — Workspace, Intelligence Feed & Autonomous Task Dashboard

USAGE:
  daily                      Launch/open the Web Dashboard in browser
  daily stop                 Stop the background server daemon
  daily restart              Restart the background server daemon
  daily status               Display process status and database metrics
  daily serve                Run server + scheduler in foreground
  daily list                 Print recent feed updates to terminal
  daily add [flags]          Add a new update entry via CLI
  daily task list            Display autonomous tasks table
  daily task trigger <id>    Manually trigger execution of task <id>
  daily task pause <id>      Pause autonomous task cron execution
  daily task resume <id>     Resume autonomous task cron execution
  daily mcp                  Start Stdio MCP server
`);
}

main().catch(err => {
  console.error('Fatal CLI Error:', err);
  process.exit(1);
});

#!/usr/bin/env node
const readline = require('node:readline');
const db = require('../data/db.js');
const scheduler = require('../server/scheduler.js');

const SERVER_NAME = 'daily-mcp';
const SERVER_VERSION = '1.1.0';

const TOOLS = [
  {
    name: 'daily_add_update',
    description: 'Add a new daily update entry (tech news, viral repo shortlist, AI tool digest) formatted in markdown.',
    inputSchema: {
      type: 'object',
      properties: {
        title: { type: 'string', description: 'Title of the update entry' },
        category: {
          type: 'string',
          enum: ['os_project', 'ai_tool', 'tech_news', 'custom'],
          description: 'Category of update'
        },
        markdown_content: { type: 'string', description: 'Full markdown body content' },
        tags: {
          type: 'array',
          items: { type: 'string' },
          description: 'Tags for categorization e.g. ["rust", "llm"]'
        },
        source_agent: { type: 'string', description: 'Name of pushing agent (default: hermes)' },
        metadata: { type: 'object', description: 'Structured metadata e.g. { repo_url: "...", stars: 1000 }' }
      },
      required: ['title', 'category', 'markdown_content']
    }
  },
  {
    name: 'daily_get_updates',
    description: 'Fetch recorded daily updates between since timestamp and now.',
    inputSchema: {
      type: 'object',
      properties: {
        since: { type: 'string', description: 'ISO timestamp e.g. 2026-08-10T00:00:00Z' },
        category: { type: 'string', description: 'Filter by category (os_project, ai_tool, tech_news, custom)' },
        limit: { type: 'number', description: 'Max number of entries to return (default 20)' }
      }
    }
  },
  {
    name: 'daily_list_tasks',
    description: 'List all registered autonomous tasks and their execution statuses.',
    inputSchema: {
      type: 'object',
      properties: {
        status_filter: { type: 'string', description: 'Optional status filter (active, paused, error)' }
      }
    }
  },
  {
    name: 'daily_add_task',
    description: 'Register a new autonomous task in the Daily Workspace, specifying which AI agent (hermes, opencode, claude, system) executes it.',
    inputSchema: {
      type: 'object',
      properties: {
        id: { type: 'string', description: 'Unique task ID e.g. opencode-repo-audit' },
        name: { type: 'string', description: 'Human readable task name' },
        command_or_prompt: { type: 'string', description: 'Command line string or agent prompt to execute' },
        schedule: { type: 'string', description: 'Schedule string e.g. every 6h, daily @ 09:00' },
        agent_type: { type: 'string', description: 'Agent executor binding: hermes, opencode, claude, system, cli (default: system)' },
        status: { type: 'string', enum: ['active', 'paused'], description: 'Initial task status' }
      },
      required: ['id', 'name', 'command_or_prompt', 'schedule']
    }
  },
  {
    name: 'daily_trigger_task',
    description: 'Manually trigger execution of a specific autonomous task using its bound agent or script.',
    inputSchema: {
      type: 'object',
      properties: {
        task_id: { type: 'string', description: 'ID of the task to execute (e.g. reddit-warmup)' }
      },
      required: ['task_id']
    }
  }
];

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout,
  terminal: false
});

rl.on('line', (line) => {
  if (!line.trim()) return;
  try {
    const request = JSON.parse(line);
    handleJsonRpcRequest(request);
  } catch (err) {
    sendJsonRpcError(null, -32700, 'Parse error', err.message);
  }
});

async function handleJsonRpcRequest(req) {
  const { id, method, params } = req;

  // Handle Notifications (no ID)
  if (id === undefined || id === null) {
    if (method === 'notifications/initialized') {
      // client initialization complete
    }
    return;
  }

  switch (method) {
    case 'initialize':
      sendJsonRpcResult(id, {
        protocolVersion: '2024-11-05',
        capabilities: {
          tools: {}
        },
        serverInfo: {
          name: SERVER_NAME,
          version: SERVER_VERSION
        }
      });
      break;

    case 'tools/list':
      sendJsonRpcResult(id, { tools: TOOLS });
      break;

    case 'tools/call':
      await handleToolCall(id, params);
      break;

    case 'ping':
      sendJsonRpcResult(id, {});
      break;

    default:
      sendJsonRpcError(id, -32601, 'Method not found', `Method ${method} is not supported.`);
      break;
  }
}

async function handleToolCall(id, params) {
  const { name, arguments: args = {} } = params || {};

  try {
    let resultText = '';

    if (name === 'daily_add_update') {
      const created = db.addUpdate({
        title: args.title,
        category: args.category,
        markdown_content: args.markdown_content,
        tags: args.tags || [],
        source_agent: args.source_agent || 'hermes',
        metadata: args.metadata || {}
      });
      resultText = `Successfully created update ID ${created.id}: "${created.title}" under category "${created.category}".`;
    } else if (name === 'daily_get_updates') {
      const updates = db.getUpdates({
        since: args.since,
        category: args.category,
        limit: args.limit || 20
      });
      resultText = JSON.stringify(updates, null, 2);
    } else if (name === 'daily_list_tasks') {
      const tasks = db.getTasks({ status: args.status_filter });
      resultText = JSON.stringify(tasks, null, 2);
    } else if (name === 'daily_add_task') {
      const created = db.addTask({
        id: args.id,
        name: args.name,
        command_or_prompt: args.command_or_prompt,
        schedule: args.schedule,
        status: args.status || 'active',
        agent_type: args.agent_type || 'system'
      });
      resultText = `Successfully registered task "${created.id}" bound to agent "${created.agent_type}".`;
    } else if (name === 'daily_trigger_task') {
      const runRes = await scheduler.runTask(args.task_id);
      resultText = `Task "${args.task_id}" execution completed:\nStatus: ${runRes.success ? 'SUCCESS' : 'FAILED'}\nOutput:\n${runRes.output}`;
    } else {
      return sendJsonRpcError(id, -32601, 'Tool not found', `Tool ${name} is not defined.`);
    }

    sendJsonRpcResult(id, {
      content: [
        {
          type: 'text',
          text: resultText
        }
      ]
    });
  } catch (err) {
    sendJsonRpcResult(id, {
      isError: true,
      content: [
        {
          type: 'text',
          text: `Error executing tool ${name}: ${err.message}`
        }
      ]
    });
  }
}

function sendJsonRpcResult(id, result) {
  const response = {
    jsonrpc: '2.0',
    id,
    result
  };
  process.stdout.write(JSON.stringify(response) + '\n');
}

function sendJsonRpcError(id, code, message, data) {
  const response = {
    jsonrpc: '2.0',
    id,
    error: {
      code,
      message,
      data
    }
  };
  process.stdout.write(JSON.stringify(response) + '\n');
}

const http = require('node:http');
const path = require('node:path');
const fs = require('node:fs');
const url = require('node:url');

const db = require('../data/db.js');
const scheduler = require('./scheduler.js');

const PORT = process.env.DAILY_PORT || 3456;
const WEB_DIST = path.join(__dirname, '..', 'web', 'dist');

function startServer(port = PORT) {
  // Start autonomous task scheduler
  scheduler.startScheduler();

  const server = http.createServer(async (req, res) => {
    // Enable CORS
    res.setHeader('Access-Control-Allow-Origin', '*');
    res.setHeader('Access-Control-Allow-Methods', 'GET, POST, PATCH, DELETE, OPTIONS');
    res.setHeader('Access-Control-Allow-Headers', 'Content-Type, Authorization');

    if (req.method === 'OPTIONS') {
      res.writeHead(204);
      return res.end();
    }

    const parsedUrl = url.parse(req.url, true);
    const pathname = parsedUrl.pathname;
    const query = parsedUrl.query;

    try {
      // REST API Routes
      if (pathname.startsWith('/api/')) {
        return handleApiRequest(req, res, pathname, query);
      }

      // Serve Static Web Frontend
      serveStaticWeb(req, res, pathname);
    } catch (err) {
      console.error('[API SERVER ERROR]', err);
      res.writeHead(500, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: err.message }));
    }
  });

  server.listen(port, () => {
    console.log(`[DAILY SERVER] Running at http://localhost:${port}`);
  });

  return server;
}

async function handleApiRequest(req, res, pathname, query) {
  res.setHeader('Content-Type', 'application/json');

  // GET /api/stats
  if (req.method === 'GET' && pathname === '/api/stats') {
    const stats = db.getStats();
    res.writeHead(200);
    return res.end(JSON.stringify(stats));
  }

  // GET /api/updates
  if (req.method === 'GET' && pathname === '/api/updates') {
    const updates = db.getUpdates({
      since: query.since,
      category: query.category,
      search: query.search,
      limit: query.limit ? parseInt(query.limit, 10) : 50,
      offset: query.offset ? parseInt(query.offset, 10) : 0,
      tag: query.tag,
      read_status: query.read_status !== undefined ? parseInt(query.read_status, 10) : undefined
    });
    res.writeHead(200);
    return res.end(JSON.stringify(updates));
  }

  // GET /api/updates/:id
  const updateMatch = pathname.match(/^\/api\/updates\/(\d+)$/);
  if (req.method === 'GET' && updateMatch) {
    const item = db.getUpdateById(parseInt(updateMatch[1], 10));
    if (!item) {
      res.writeHead(404);
      return res.end(JSON.stringify({ error: 'Update not found' }));
    }
    res.writeHead(200);
    return res.end(JSON.stringify(item));
  }

  // POST /api/updates
  if (req.method === 'POST' && pathname === '/api/updates') {
    const body = await parseJsonBody(req);
    if (!body.title || !body.category || !body.markdown_content) {
      res.writeHead(400);
      return res.end(JSON.stringify({ error: 'Missing required fields: title, category, markdown_content' }));
    }
    const created = db.addUpdate(body);
    res.writeHead(201);
    return res.end(JSON.stringify(created));
  }

  // PATCH /api/updates/:id/read
  const readMatch = pathname.match(/^\/api\/updates\/(\d+)\/read$/);
  if (req.method === 'PATCH' && readMatch) {
    const body = await parseJsonBody(req);
    const readStatus = body.read_status !== undefined ? body.read_status : 1;
    const updated = db.markUpdateRead(parseInt(readMatch[1], 10), readStatus);
    res.writeHead(200);
    return res.end(JSON.stringify(updated));
  }

  // DELETE /api/updates/:id
  if (req.method === 'DELETE' && updateMatch) {
    const deleted = db.deleteUpdate(parseInt(updateMatch[1], 10));
    res.writeHead(200);
    return res.end(JSON.stringify({ success: deleted }));
  }

  // GET /api/tasks
  if (req.method === 'GET' && pathname === '/api/tasks') {
    const tasks = db.getTasks({ status: query.status });
    res.writeHead(200);
    return res.end(JSON.stringify(tasks));
  }

  // GET /api/tasks/:id
  const taskMatch = pathname.match(/^\/api\/tasks\/([a-zA-Z0-9_-]+)$/);
  if (req.method === 'GET' && taskMatch) {
    const task = db.getTaskById(taskMatch[1]);
    if (!task) {
      res.writeHead(404);
      return res.end(JSON.stringify({ error: 'Task not found' }));
    }
    res.writeHead(200);
    return res.end(JSON.stringify(task));
  }

  // POST /api/tasks
  if (req.method === 'POST' && pathname === '/api/tasks') {
    const body = await parseJsonBody(req);
    if (!body.id || !body.name || !body.command_or_prompt || !body.schedule) {
      res.writeHead(400);
      return res.end(JSON.stringify({ error: 'Missing required fields: id, name, command_or_prompt, schedule' }));
    }
    const created = db.addTask(body);
    res.writeHead(201);
    return res.end(JSON.stringify(created));
  }

  // PATCH /api/tasks/:id
  if (req.method === 'PATCH' && taskMatch) {
    const body = await parseJsonBody(req);
    const updated = db.updateTask(taskMatch[1], body);
    res.writeHead(200);
    return res.end(JSON.stringify(updated));
  }

  // POST /api/tasks/:id/trigger
  const triggerMatch = pathname.match(/^\/api\/tasks\/([a-zA-Z0-9_-]+)\/trigger$/);
  if (req.method === 'POST' && triggerMatch) {
    const result = await scheduler.runTask(triggerMatch[1]);
    res.writeHead(200);
    return res.end(JSON.stringify(result));
  }

  // GET /api/tasks/:id/logs
  const logsMatch = pathname.match(/^\/api\/tasks\/([a-zA-Z0-9_-]+)\/logs$/);
  if (req.method === 'GET' && logsMatch) {
    const logs = db.getTaskLogs(logsMatch[1], query.limit ? parseInt(query.limit, 10) : 20);
    res.writeHead(200);
    return res.end(JSON.stringify(logs));
  }

  // DELETE /api/tasks/:id
  if (req.method === 'DELETE' && taskMatch) {
    const deleted = db.deleteTask(taskMatch[1]);
    res.writeHead(200);
    return res.end(JSON.stringify({ success: deleted }));
  }

  res.writeHead(404);
  res.end(JSON.stringify({ error: 'Endpoint not found' }));
}

function serveStaticWeb(req, res, pathname) {
  let filePath = path.join(WEB_DIST, pathname === '/' ? 'index.html' : pathname);

  // Fallback to index.html for SPA client-side routing if file doesn't exist
  if (!fs.existsSync(filePath) || fs.statSync(filePath).isDirectory()) {
    filePath = path.join(WEB_DIST, 'index.html');
  }

  if (!fs.existsSync(filePath)) {
    res.writeHead(404, { 'Content-Type': 'text/plain' });
    return res.end('Daily Web Interface not built yet. Run build step or start dev server.');
  }

  const ext = path.extname(filePath).toLowerCase();
  const mimeTypes = {
    '.html': 'text/html',
    '.js': 'application/javascript',
    '.css': 'text/css',
    '.json': 'application/json',
    '.png': 'image/png',
    '.jpg': 'image/jpeg',
    '.svg': 'image/svg+xml',
    '.ico': 'image/x-icon',
    '.woff2': 'font/woff2'
  };

  const contentType = mimeTypes[ext] || 'application/octet-stream';
  res.writeHead(200, { 'Content-Type': contentType });
  fs.createReadStream(filePath).pipe(res);
}

function parseJsonBody(req) {
  return new Promise((resolve, reject) => {
    let body = '';
    req.on('data', chunk => { body += chunk; });
    req.on('end', () => {
      try {
        resolve(body ? JSON.parse(body) : {});
      } catch (err) {
        reject(new Error('Invalid JSON payload'));
      }
    });
    req.on('error', reject);
  });
}

